<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>{{ $title ?? 'Campus POS' }}</title><style>:root{--navy:#102a43;--blue:#1f5f99;--ink:#243b53;--muted:#627d98;--paper:#f7fafc;--line:#d9e2ec;--green:#16803c;--amber:#b7791f;--red:#c53030}*{box-sizing:border-box}body{margin:0;font-family:Arial,Helvetica,sans-serif;color:var(--ink);background:var(--paper)}.shell{width:min(1100px,calc(100% - 40px));margin:auto}header{background:var(--navy);color:#fff}.nav{min-height:68px;display:flex;align-items:center;justify-content:space-between;gap:24px}.brand{color:#fff;text-decoration:none;font-size:1.2rem;font-weight:700}nav{display:flex;flex-wrap:wrap;gap:4px}nav a{color:#d9e2ec;text-decoration:none;padding:9px 11px;border-radius:5px;font-size:.92rem}nav a:hover,nav a.active{color:#fff;background:#243b53}main{padding:48px 0 64px}.eyebrow{color:var(--blue);font-size:.78rem;font-weight:700;letter-spacing:.1em;text-transform:uppercase;margin:0 0 10px}h1{font-size:clamp(2rem,5vw,3.2rem);line-height:1.1;margin:0 0 16px;color:var(--navy)}h2{color:var(--navy);margin-top:0}p{line-height:1.65}.lead{max-width:700px;color:var(--muted);font-size:1.08rem}.hero{padding:46px;border-radius:14px;background:linear-gradient(135deg,#e7f0f8,#fff);border:1px solid var(--line)}.button{display:inline-block;margin:12px 10px 0 0;padding:11px 16px;background:var(--blue);color:#fff;text-decoration:none;border-radius:6px;font-weight:700}.button.secondary{background:#fff;color:var(--blue);border:1px solid var(--blue)}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:28px}.card{padding:22px;background:#fff;border:1px solid var(--line);border-radius:10px}.card h2{font-size:1.05rem;margin-bottom:8px}.card p{color:var(--muted);margin:0;font-size:.94rem}.page-head{margin-bottom:26px}.table-wrap{overflow-x:auto;background:#fff;border:1px solid var(--line);border-radius:10px}table{width:100%;border-collapse:collapse;min-width:700px}th,td{padding:15px 16px;border-bottom:1px solid var(--line);text-align:left}th{background:#e7f0f8;color:var(--navy);font-size:.8rem;text-transform:uppercase;letter-spacing:.06em}tr:last-child td{border-bottom:0}td{font-size:.94rem}.badge{display:inline-block;padding:4px 9px;border-radius:999px;font-size:.76rem;font-weight:700}.active{background:#dcfce7;color:var(--green)}.pending{background:#fef3c7;color:var(--amber)}.inactive{background:#fee2e2;color:var(--red)}.about{max-width:760px;background:#fff;padding:30px;border:1px solid var(--line);border-radius:10px}footer{padding:24px 0;border-top:1px solid var(--line);color:var(--muted);font-size:.85rem}@media(max-width:700px){.nav{padding:14px 0;align-items:flex-start;flex-direction:column;gap:8px}main{padding-top:30px}.hero{padding:28px}.grid{grid-template-columns:1fr}}</style></head><body><header><div class="shell nav"><a class="brand" href="{{ route('home') }}">Campus POS</a><nav><a class="{{ request()->routeIs('home') ? 'active' : '' }}" href="{{ route('home') }}">Home</a><a class="{{ request()->routeIs('about') ? 'active' : '' }}" href="{{ route('about') }}">About</a><a class="{{ request()->routeIs('customers.*') ? 'active' : '' }}" href="{{ route('customers.index') }}">Customers</a><a class="{{ request()->routeIs('users.*') ? 'active' : '' }}" href="{{ route('users.index') }}">Users</a></nav></div></header><main class="shell">@yield('content')</main><footer><div class="shell">Campus POS &middot; Laravel POS Foundations</div></footer></body></html>
